const menu=document.querySelector('.menu-toggle');menu?.addEventListener('click',()=>{const el=document.querySelector('.header-right');const open=el.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'閉じる':'メニュー'});
const dialog=document.getElementById('lightbox');document.querySelector('.close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelectorAll('[data-enlarge]').forEach(b=>b.addEventListener('click',()=>{const wrap=document.getElementById('lightbox-content');wrap.replaceChildren();const img=document.createElement('img');img.src=b.dataset.enlarge;img.alt=b.querySelector('img')?.alt||'拡大画像';wrap.append(img);dialog.showModal()}));
let filter='all';const search=document.getElementById('search-products');function applyFilter(){const q=search?.value.trim()||'';let count=0;document.querySelectorAll('.product-card[data-category]').forEach(p=>{const show=(filter==='all'||filter===p.dataset.category)&&(!q||p.dataset.search.includes(q));p.hidden=!show;if(show)count++});const out=document.getElementById('result-count');if(out)out.textContent=count+'件の商品';const none=document.getElementById('no-products');if(none)none.hidden=count>0}search?.addEventListener('input',applyFilter);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));applyFilter()}));if(search&&location.hash==='#rice'){filter='お米';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter===filter));applyFilter()}
const additionalEvents={'2026-10-31':'秋の収穫フェア 9:00–15:00','2026-11-7':'ゆりいち朝市 9:00–12:00','2026-11-14':'花と緑のミニマルシェ 10:00–14:00'};let year=2026,month=9;const grid=document.getElementById('month-grid');function dayInfo(y,m,d){const extra=additionalEvents[y+'-'+(m+1)+'-'+d];if(extra)return extra;const weekday=new Date(y,m,d).getDay();if(weekday===2)return '定休日';if(y===2026&&m===9&&d===17)return '秋の農家さんマルシェ 10:00–14:00';if(y===2026&&m===9&&d===24)return '親子で楽しむ、旬の野菜教室 11:00–12:00';return 'ゆりいち 9:00–17:00'}function pickDay(d){document.getElementById('selected-date').textContent=year+'年'+(month+1)+'月'+d+'日';document.getElementById('selected-info').textContent=dayInfo(year,month,d);grid.querySelectorAll('button').forEach(b=>b.classList.toggle('chosen',+b.dataset.day===d))}function renderMonth(){if(!grid)return;document.getElementById('month-title').textContent=year+'年'+(month+1)+'月';grid.replaceChildren();['日','月','火','水','木','金','土'].forEach(x=>{const s=document.createElement('span');s.className='weekday';s.textContent=x;grid.append(s)});const offset=new Date(year,month,1).getDay();for(let i=0;i<offset;i++)grid.append(document.createElement('span'));const max=new Date(year,month+1,0).getDate();for(let d=1;d<=max;d++){const b=document.createElement('button');b.dataset.day=d;const rest=new Date(year,month,d).getDay()===2,evt=(year===2026&&month===9&&[17,24].includes(d))||Boolean(additionalEvents[year+'-'+(month+1)+'-'+d]);b.className=rest?'rest':evt?'event':'';b.innerHTML=d+(rest?'<small>休</small>':evt?'<small>催</small>':'');b.setAttribute('aria-label',year+'年'+(month+1)+'月'+d+'日 '+dayInfo(year,month,d));b.onclick=()=>pickDay(d);grid.append(b)}pickDay(year===2026&&month===9?15:1)}document.getElementById('prev-month')?.addEventListener('click',()=>{month--;if(month<0){month=11;year--}renderMonth()});document.getElementById('next-month')?.addEventListener('click',()=>{month++;if(month>11){month=0;year++}renderMonth()});renderMonth();
const form=document.getElementById('contact-form');if(form&&new URLSearchParams(location.search).get('type')==='producer')form.elements.type.value='出品について';form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),wrap=document.getElementById('lightbox-content');wrap.replaceChildren();const title=document.createElement('h2');title.textContent='入力内容の確認';wrap.append(title);for(const [key,label] of [['type','種類'],['name','お名前'],['email','メールアドレス'],['phone','電話番号'],['message','お問い合わせ内容']]){const row=document.createElement('div');row.className='confirm-row';const b=document.createElement('b'),p=document.createElement('p');b.textContent=label;p.textContent=data.get(key)||'未入力';row.append(b,p);wrap.append(row)}const note=document.createElement('p');note.textContent='入力内容をご確認ください。';note.className='small';wrap.append(note);const back=document.createElement('button');back.className='button';back.textContent='入力画面に戻る';back.onclick=()=>dialog.close();wrap.append(back);dialog.showModal()});
const heroIndex=document.querySelector('.hero-index');if(heroIndex){const items=[['assets/market-interior.webp','直売所の店内イメージ'],['assets/market-hq.webp','ゆりいちの店舗外観'],['assets/park-hq.webp','ゆりの里公園の風景']];heroIndex.replaceChildren();items.forEach((it,i)=>{const b=document.createElement('button');b.type='button';b.className=i===0?'active':'';b.setAttribute('aria-label','写真'+(i+1)+'を表示');b.setAttribute('aria-pressed',String(i===0));b.onclick=()=>{const img=document.querySelector('.hero-frame img');img.src=it[0];img.alt=it[1];heroIndex.querySelectorAll('button').forEach((x,j)=>{x.classList.toggle('active',j===i);x.setAttribute('aria-pressed',String(j===i))})};heroIndex.append(b)})}

const selectedFarmer=new URLSearchParams(location.search).get("farmer");if(search&&selectedFarmer){search.value=selectedFarmer;applyFilter()}
